# -*- coding: utf-8 -*-
"""Tests for ``le_save_import`` (offline Last Epoch save -> BD extraction).

Run from ``tools/save_import``::

    <python> -m unittest discover -s tests -v

The fixtures under ``tests/fixtures`` are read-only copies:
  * ``1CHARACTERSLOT_BETA_2``      — character save generated by lastepochsupertools v1.3.1
  * ``STASH_0``                    — matching stash save
  * ``planner-build-response.json`` — Letools planner payload of build ``o3ZRm9my``
"""
from __future__ import annotations

import json
import sys
import tempfile
import unittest
from pathlib import Path

TOOL_ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(TOOL_ROOT / "src"))

from le_save_import import compare_to_planner, extract_build, run_pipeline  # noqa: E402
from le_save_import import items as save_items  # noqa: E402
from le_save_import import stash as save_stash  # noqa: E402
from le_save_import.names import Resolver, decode_planner_id  # noqa: E402
from le_save_import.pipeline import BLESSING_TIMELINE, EQUIPMENT_SLOTS  # noqa: E402

FIXTURES = Path(__file__).resolve().parent / "fixtures"
SAVE = FIXTURES / "1CHARACTERSLOT_BETA_2"
STASH = FIXTURES / "STASH_0"
PLANNER = FIXTURES / "planner-build-response.json"


class SaveContainerTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.doc = save_items.load_save(SAVE)

    def test_epoch_container(self):
        self.assertEqual(self.doc["characterName"], "BlaCFEditor")
        self.assertEqual(self.doc["level"], 100)
        self.assertEqual(self.doc["characterClass"], 1)
        self.assertEqual(self.doc["chosenMastery"], 1)
        self.assertEqual(len(self.doc["savedItems"]), 43)

    def test_wrong_magic_rejected(self):
        with tempfile.NamedTemporaryFile(suffix=".save", delete=False) as fh:
            fh.write(b"NOPE{}")
            path = Path(fh.name)
        try:
            with self.assertRaises(save_items.DecodeError):
                save_items.load_save(path)
        finally:
            path.unlink()

    def test_stash_lists(self):
        stash = save_items.load_save(STASH)
        lists = save_stash.decrypt_stash_lists(stash)
        self.assertEqual(len(lists["materialsList"]), 19)
        self.assertEqual(len(lists["wovenEchoesList"]), 44)
        self.assertEqual(len(lists["keysList"]), 17)


class ItemDecodeTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.doc = save_items.load_save(SAVE)
        cls.items = save_items.decode_save_items(cls.doc)

    def test_all_items_decode(self):
        self.assertEqual(len(self.items), 43)
        for item in self.items:
            self.assertEqual(item["format_version"], 6, item.get("index"))
            self.assertIsInstance(item["affixes"], list)
            self.assertIn("byte_exact", item)

    def test_game_faithful_byte_consumption(self):
        # The primary layout is the one written by the generator tool (all 43 exact).
        # Retail-game loader readings are attached separately (game_loader_interpretation);
        # items 19/20 are Woven Echoes written in the editor's generic plain layout.
        self.assertTrue(all(i["byte_exact"] for i in self.items))
        by_index = {i["index"]: i for i in self.items}
        for idx in (19, 20):
            self.assertEqual(by_index[idx]["layout"], "editor-plain-non-equippable")
            self.assertIsNotNone(by_index[idx]["game_loader_interpretation"])
        self.assertEqual(by_index[8]["layout"], "game-non-equippable")
        self.assertEqual(sum(1 for i in self.items if i["layout"] == "equipment"), 40)

    def test_equipment_identity_matches_planner(self):
        by_cid = {i["container_id"]: i for i in self.items}
        expected = {
            2: (0, 23, 316),    # head: Runed Visage / Apex of Thought
            3: (1, 58, 275),    # chest: Arcane Regalia / Unstable Core
            4: (16, 7, 330),    # weapon1: Flamberge / Spine of Malatros
            6: (4, 3, 479),     # hands: Outcast Gloves / Withstand the Elements
            8: (3, 6, 91),      # feet: Solarum Greaves / Fiery Dragon Shoes
            9: (21, 10, 477),   # ring2 (EQ_RIGHTRING): Opal Ring / Unsated Rage
            11: (20, 2, 175),   # amulet: Silver Amulet / Omnis
        }
        for cid, (base, sub, unique) in expected.items():
            self.assertEqual(by_cid[cid]["base_type_id"], base, f"container {cid}")
            self.assertEqual(by_cid[cid]["sub_type_id"], sub, f"container {cid}")
            self.assertEqual(by_cid[cid]["unique_id"], unique, f"container {cid}")

    def test_idol_rolls_match_planner(self):
        planner = json.loads(PLANNER.read_text(encoding="utf-8"))["data"]
        idols = [i for i in self.items if i["container_id"] == 29]
        self.assertEqual(len(idols), 8)
        for save_idol, planner_idol in zip(idols, planner["idols"]):
            planned = [(decode_planner_id(a["id"])["affix_id"], a["tier"], a["r"])
                       for a in planner_idol.get("affixes") or []]
            corrupted = planner_idol.get("corruptedAffix")
            if corrupted:
                planned.append((decode_planner_id(corrupted["id"])["affix_id"],
                                corrupted["tier"], corrupted["r"]))
            got = {(a["affix_id"], a["tier"], a["roll"]) for a in save_idol["affixes"]}
            self.assertEqual(got, set(planned))

    def test_reencode_roundtrip(self):
        # The generator's writer rules are the exact inverse of this decoder.
        for item, entry in zip(self.items, self.doc["savedItems"]):
            reencoded = save_items.encode_item(item)
            self.assertEqual(reencoded, [int(b) & 0xFF for b in entry["data"]],
                             f"roundtrip mismatch at index {item['index']}")


class ResolverTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.r = Resolver()

    def test_containers(self):
        self.assertEqual(self.r.container_name(2), "EQ_HELMET")
        self.assertEqual(self.r.container_name(29), "IDOLS")
        self.assertEqual(self.r.container_name(123), "IDOLS_INVENTORY")
        self.assertEqual(self.r.container(9)["planner_role"], "equipment.ring2")

    def test_uniques(self):
        self.assertEqual(self.r.unique(477)["name"], "Unsated Rage")
        self.assertEqual(self.r.unique(479)["name"], "Withstand the Elements")
        self.assertEqual(self.r.unique(316)["name"], "Apex of Thought")

    def test_class_and_trees(self):
        self.assertEqual(self.r.class_name(1)["name"], "Mage")
        self.assertEqual(self.r.mastery(1, 1)["name"], "Sorcerer")
        self.assertEqual(self.r.skill_tree("bh2")["name"], "Black Hole")
        self.assertEqual(self.r.skill_tree_node("bh2", 2)["name"], "Tidal Force")
        self.assertEqual(self.r.passive_node(1, 0)["name"], "Arcanist")

    def test_affixes(self):
        self.assertEqual(self.r.affix(1147)["tier_count"], 8)
        self.assertIn("Fire Resistance", self.r.affix(13, tier0=6)["name"])
        self.assertEqual(self.r.blessing(116)["name"], "Grand Scales of Greed")


class BuildExtractionTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.build = extract_build(SAVE)

    def test_counts(self):
        counts = self.build["counts"]
        self.assertEqual(counts["equipment"], 11)  # 10 gear slots + idol_altar
        self.assertEqual(counts["idols"], 8)
        self.assertEqual(counts["blessings"], 10)
        self.assertEqual(counts["weaver_tree_items"], 5)
        self.assertEqual(counts["other"], 9)  # 4 nemesis + 5 rage-of-morditas
        self.assertEqual(counts["total"], 43)
        self.assertEqual(self.build["identity"]["class"]["name"], "Mage")
        self.assertEqual(self.build["identity"]["chosen_mastery"]["name"], "Sorcerer")

    def test_trees_and_hud(self):
        self.assertEqual(self.build["passive_tree"]["points_total"], 113)
        self.assertEqual(self.build["passive_tree"]["node_count"], 19)
        self.assertEqual(len(self.build["specializations"]), 5)
        self.assertEqual(sum(t["points_total"] for t in self.build["specializations"]), 128)
        self.assertEqual(sum(t["node_count"] for t in self.build["specializations"]), 61)
        self.assertEqual(self.build["weaver_tree"]["points_total"], 32)
        self.assertEqual(self.build["weaver_tree"]["node_count"], 22)
        hud = [b["id"] for b in self.build["ability_bar"]]
        self.assertEqual(hud, ["me27", "sb44eQ", "te44", "fr4wl", "bh2"])
        self.assertEqual(sum(1 for b in self.build["ability_bar"] if b["specialized"]), 4)

    def test_equipment_names_and_channels(self):
        equipment = self.build["equipment"]
        self.assertEqual(equipment["head"]["unique"]["name"], "Apex of Thought")
        self.assertEqual(equipment["weapon1"]["unique"]["name"], "Spine of Malatros")
        hands = equipment["hands"]
        self.assertEqual(hands["unique"]["name"], "Withstand the Elements")
        first = hands["affixes"][0]
        self.assertEqual(first["affix_id"], 1147)
        self.assertEqual(first["channel_editor"], "sealed")  # editor intent
        self.assertEqual(first["channel_game"], "normal")    # game reads weaversWill bits
        altar = equipment["idol_altar"]
        self.assertEqual(altar["base"]["name"], "Pyramidal Altar")
        self.assertEqual(altar["affixes"][0]["channel_editor"], "corrupted")
        self.assertTrue(altar["editor_maxed"]["implicit_rolls_all_255"])
        # editor-written items use the instance-id sentinel / max roll values
        self.assertTrue(equipment["head"]["editor_maxed"]["instance_id_is_editor_constant"])

    def test_affix_db_per_base_ranges(self):
        """Per-base ranges (2H weapon / body armour) are used by the BD document."""
        if (self.build.get("provenance", {}).get("affix_db") or {}).get("status") != "available":
            self.skipTest("normalized affix DB not present")
        weapon = self.build["equipment"]["weapon1"]["affixes"][0]
        self.assertEqual(weapon["affix_id"], 720)
        self.assertIn("35-40", weapon["text"])
        self.assertAlmostEqual(weapon["affix_db"]["effective_value"], 0.40, places=12)
        self.assertEqual(weapon["affix_db"]["base_type_id"], 16)  # Two-Handed Sword
        chest = self.build["equipment"]["chest"]["affixes"][0]
        self.assertIn("92-112", chest["text"])
        self.assertAlmostEqual(chest["affix_db"]["effective_value"], 1.12, places=12)
        self.assertEqual(chest["affix_db"]["base_type_id"], 1)  # Body Armor
        amulet = self.build["equipment"]["amulet"]["affixes"][0]
        self.assertEqual(amulet["affix_id"], 100)
        self.assertIn("200-257", amulet["text"])
        self.assertAlmostEqual(amulet["affix_db"]["effective_value"], 2.57, places=12)
        self.assertEqual(amulet["affix_db"]["base_type_id"], 20)  # Amulet

    def test_blessing_timeline_order(self):
        names = [self.build["blessings"][str(t)]["name"] for t in range(1, 11)]
        self.assertEqual(names[0], "Grand Scales of Greed")
        self.assertEqual(names[2], "Grand Greed of Darkness")
        self.assertEqual(names[9], "Grand Heart of the Caldera")

    def test_container_enum_tables(self):
        self.assertEqual(EQUIPMENT_SLOTS[9], "ring2")
        self.assertEqual(EQUIPMENT_SLOTS[10], "ring1")
        self.assertEqual(BLESSING_TIMELINE[43], 8)

    def test_comparison_against_planner(self):
        comparison = compare_to_planner(self.build, PLANNER)
        self.assertEqual(comparison["summary"]["mismatch"], 0)
        checks = {c["id"]: c for c in comparison["checks"]}
        self.assertEqual(checks["identity"]["result"], "match")
        self.assertEqual(checks["passive_tree"]["result"], "match")
        self.assertEqual(checks["skill_trees"]["result"], "match")
        self.assertEqual(checks["ability_bar"]["result"], "match")
        self.assertEqual(checks["equipment_identity"]["result"], "match")
        self.assertEqual(checks["idols"]["result"], "match")
        self.assertEqual(checks["blessings"]["result"], "match")
        self.assertEqual(checks["weaver_tree_items"]["result"], "match")
        # documented save-editor deviations:
        self.assertEqual(checks["equipment_affixes"]["result"], "partial")
        self.assertEqual(len(checks["equipment_affixes"]["deviations"]), 2)
        self.assertEqual(checks["quests"]["result"], "partial")  # planner-only 158

    def test_deterministic_build_core(self):
        again = extract_build(SAVE)
        for key in ("identity", "ability_bar", "passive_tree", "specializations",
                    "weaver_tree", "counts", "blessings"):
            self.assertEqual(json.dumps(self.build[key], sort_keys=True, ensure_ascii=False),
                             json.dumps(again[key], sort_keys=True, ensure_ascii=False), key)


class PipelineOutputTests(unittest.TestCase):
    def test_run_pipeline_writes_artifacts(self):
        with tempfile.TemporaryDirectory() as tmp:
            result = run_pipeline(SAVE, tmp, planner_path=PLANNER, stash_path=STASH)
            paths = result["paths"]
            for key in ("build", "tables", "items", "extract", "comparison", "stash"):
                self.assertIn(key, paths)
                self.assertTrue(Path(paths[key]).is_file(), key)
            build = json.loads(Path(paths["build"]).read_text(encoding="utf-8"))
            self.assertEqual(build["schema"], "save-build-v1")
            self.assertEqual(build["source"]["sha256"],
                             "0448f11302f955a2f96e3eca491c4718e0c434c3efbc57aadb64f4c860180813")
            self.assertEqual(build["source"]["size_bytes"], 53768)


if __name__ == "__main__":
    unittest.main()
